import React,{useEffect,useMemo,useState}from"react";
import{createRoot}from"react-dom/client";
import"./styles.css";

const API=import.meta.env.VITE_API_URL||"http://127.0.0.1:8010/api";
let token=null;

async function api(path,opt={},retry=true){
  const h=new Headers(opt.headers||{});
  if(token)h.set("Authorization",`Bearer ${token}`);
  if(opt.body&&!h.has("Content-Type"))h.set("Content-Type","application/json");
  const r=await fetch(API+path,{...opt,headers:h,credentials:"include"});
  if(r.status===401&&retry){
    try{const rr=await fetch(API+"/auth/refresh",{method:"POST",credentials:"include"});if(!rr.ok)throw Error();const d=await rr.json();token=d.access_token;return api(path,opt,false)}catch{}
  }
  const text=await r.text();let d={};try{d=text?JSON.parse(text):{}}catch{d={detail:text}};
  if(!r.ok){let m=d.detail;if(Array.isArray(m))m=m.map(x=>x?.msg||x?.message||String(x)).join(" | ");if(m&&typeof m==="object")m=m.msg||m.message||JSON.stringify(m);const err=new Error(m||"Erro na API");err.status=r.status;throw err}
  return d;
}
async function login(email,password){const d=await api("/auth/login",{method:"POST",body:JSON.stringify({email,password})},false);if(d.user?.role!=="admin")throw Error("Esta conta não possui acesso administrativo.");token=d.access_token;return d.user}
async function restore(){try{const d=await api("/auth/refresh",{method:"POST"},false);if(d.user?.role!=="admin")throw Error();token=d.access_token;return d.user}catch{token=null;return null}}
async function logout(){try{await api("/auth/logout",{method:"POST"},false)}catch{}token=null}

const money=v=>Number(v||0).toLocaleString("pt-BR");
const dt=v=>v?new Date(v).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short",timeZone:"America/Sao_Paulo"}):"—";
const labels={open:"Inscrições",live:"Ao vivo",finished:"Encerrado",cancelled:"Cancelado",deleted:"Excluído",free:"Gratuito",paid:"Pago"};
const slug=v=>String(v||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,80);

function Login({onAuth}){
 const[e,setE]=useState("admin@farejador.local"),[p,setP]=useState("ChangeThisPassword123!"),[busy,setBusy]=useState(false),[err,setErr]=useState("");
 async function go(x){x.preventDefault();setBusy(true);setErr("");try{onAuth(await login(e,p))}catch(x){setErr(x.message)}finally{setBusy(false)}}
 return <div className="login"><div className="login-orb"/><form className="login-box" onSubmit={go}><div className="logo">🏆</div><span className="eyebrow">BATALHA FAREJADOR</span><h1>Gestão de <strong>torneios</strong></h1><p>O centro especializado para criar, configurar, ativar, acompanhar e controlar as arenas.</p><label>Usuário administrador<input type="email" value={e} onChange={x=>setE(x.target.value)} autoComplete="username" required/></label><label>Senha<input type="password" value={p} onChange={x=>setP(x.target.value)} autoComplete="current-password" required/></label>{err&&<div className="error">{err}</div>}<button className="btn primary full" disabled={busy}>{busy?"Entrando…":"Entrar na gestão"}</button><small>Mesmas credenciais do administrador do sistema · Brasília</small></form></div>
}
function Stat({icon,title,value,sub,tone=""}){return <div className={`stat ${tone}`}><span>{icon}</span><div><b>{value}</b><small>{title}</small>{sub&&<em>{sub}</em>}</div></div>}
function Modal({children,onClose,title,wide=false}){return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal ${wide?"modal-wide":""}`} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">CENTRO DE GESTÃO</span><h2>{title}</h2></div><button className="icon-btn" type="button" onClick={onClose}>×</button></div>{children}</div></div>}
function Toast({text,onClose}){if(!text)return null;return <div className="toast"><span>✓</span>{text}<button onClick={onClose}>×</button></div>}
function Header({title,subtitle,action}){return <div className="page-head"><div><span className="eyebrow">CENTRO DE GESTÃO</span><h1>{title}</h1><p>{subtitle}</p></div><div className="head-actions"><span className="timezone">◷ Brasília · America/Sao_Paulo</span>{action}</div></div>}
function Field({label,children,wide=false,hint}){return <label className={wide?"wide-field":""}><span>{label}</span>{children}{hint&&<em className="field-hint">{hint}</em>}</label>}
function NumberInput({value,onChange,min,max,placeholder,disabled=false}){return <input type="number" min={min} max={max} value={value??""} placeholder={placeholder} disabled={disabled} onChange={e=>onChange(e.target.value)}/>}

const emptyForm={id_config:"",ativo:true,nome:"",categoria:"perfil",tema_id:"cidades",modalidade:"gratuito",participantes_minimo:"2",participantes_maximo:"8",inscricao_minutos:"15",inicio_apos_lotacao_minutos:"5",duelo_minutos:"6",quantidade_opcoes:"2",quantidade_respostas:"2",entrada_valor:"0",premiacao_tipo:"fixa",premiacao_valor:"100",primeiro:"50",segundo:"35",organizador:"10",sistema:"5"};
function toForm(c){if(!c||!c.id_config)return {...emptyForm};return {id_config:c.id_config,ativo:c.ativo!==false,nome:c.nome||"",categoria:c.categoria||"perfil",tema_id:c.tema_id||c.card?.tema_id||"cidades",modalidade:c.modalidade||"gratuito",participantes_minimo:String(c.participantes?.minimo??2),participantes_maximo:String(c.participantes?.maximo??8),inscricao_minutos:String(c.tempo?.inscricao_minutos??15),inicio_apos_lotacao_minutos:String(c.tempo?.inicio_apos_lotacao_minutos??5),duelo_minutos:String(c.tempo?.duelo_minutos??6),quantidade_opcoes:String(c.card?.quantidade_opcoes??2),quantidade_respostas:String(c.duelo?.quantidade_respostas??2),entrada_valor:String(c.entrada?.valor??0),premiacao_tipo:c.premiacao?.tipo||"fixa",premiacao_valor:String(c.premiacao?.valor??100),primeiro:String(c.premiacao?.primeiro??50),segundo:String(c.premiacao?.segundo??35),organizador:String(c.premiacao?.organizador??10),sistema:String(c.premiacao?.sistema??5)} }

function ConfigForm({initial,data,onDone}){
 const[f,setF]=useState({...emptyForm,...toForm(initial)}),[saving,setSaving]=useState(false),[err,setErr]=useState("");
 const categories=(data?.categorias||[]).filter(x=>x.ativa||x.id===f.categoria);const themes=data?.temas?.[f.categoria]||[];const theme=themes.find(x=>x.id===f.tema_id)||themes[0];
 useEffect(()=>{if(!f.tema_id&&themes[0])setF(x=>({...x,tema_id:themes[0].id}))},[f.categoria,themes.length]);
 const total=[f.primeiro,f.segundo,f.organizador,f.sistema].reduce((a,v)=>a+Number(v||0),0);
 const set=(k,v)=>setF(x=>({...x,[k]:v}));
 async function save(){
  setErr("");const max=Number(f.participantes_maximo),min=Number(f.participantes_minimo),qty=Number(f.quantidade_opcoes),answers=Number(f.quantidade_respostas);
  if(!f.nome.trim())return setErr("Informe o nome do torneio.");if(!f.id_config.trim())return setErr("Informe o ID da configuração.");if(!theme)return setErr("Selecione um tema válido.");if(max<min)return setErr("Máximo de participantes não pode ser menor que o mínimo.");if(qty<1||qty>theme.opcoes.length)return setErr(`O tema possui ${theme.opcoes.length} opções; ajuste a quantidade do card.`);if(answers<1||answers>qty)return setErr("Respostas não podem superar as opções do card.");if(total!==100)return setErr("A distribuição da premiação deve somar 100%.");
  setSaving(true);try{const payload={...f,participantes_minimo:min,participantes_maximo:max,inscricao_minutos:Number(f.inscricao_minutos),inicio_apos_lotacao_minutos:Number(f.inicio_apos_lotacao_minutos),duelo_minutos:Number(f.duelo_minutos),quantidade_opcoes:qty,quantidade_respostas:answers,entrada_valor:Number(f.entrada_valor),premiacao_valor:Number(f.premiacao_valor),primeiro:Number(f.primeiro),segundo:Number(f.segundo),organizador:Number(f.organizador),sistema:Number(f.sistema)};await api(f.id_config&&initial?.id_config?`/tournaments/admin/configs/${encodeURIComponent(f.id_config)}`:"/tournaments/admin/configs",{method:"POST",body:JSON.stringify(payload)});window.dispatchEvent(new Event("torneios:changed"));onDone("Configuração salva. Uma nova edição é criada automaticamente quando a configuração estiver ativa e não houver outra edição aberta/ao vivo.")}catch(x){setErr(x.message)}finally{setSaving(false)}
 }
 return <div className="form-body">
  <div className="form-section"><h3>1. Identidade da arena</h3><div className="grid2"><Field label="Nome do torneio" wide><input value={f.nome} onChange={e=>set("nome",e.target.value)} placeholder="Ex.: Arena Perfil · Cidades"/></Field><Field label="ID interno da configuração" hint="Use apenas letras, números e _. Não altere IDs já existentes."><input value={f.id_config} disabled={!!initial?.id_config} onChange={e=>set("id_config",e.target.value)} placeholder={slug(f.nome)||"perfil_cidades_001"}/></Field><Field label="Categoria"><select value={f.categoria} onChange={e=>{const cat=e.target.value;const first=(data?.temas?.[cat]||[])[0];setF(x=>({...x,categoria:cat,tema_id:first?.id||""}))}}>{categories.map(x=><option key={x.id} value={x.id}>{x.nome}</option>)}</select></Field><Field label="Tema"><select value={theme?.id||""} onChange={e=>set("tema_id",e.target.value)}>{themes.map(x=><option key={x.id} value={x.id}>{x.nome}</option>)}</select></Field></div></div>
  <div className="form-section"><h3>2. Entrada e participantes</h3><div className="segmented"><button type="button" className={f.modalidade==="gratuito"?"selected":""} onClick={()=>setF(x=>({...x,modalidade:"gratuito",entrada_valor:"0"}))}>🎟️ Gratuito</button><button type="button" className={f.modalidade==="pago"?"selected":""} onClick={()=>set("modalidade","pago")}>💰 Com entrada</button></div><div className="grid4"><Field label="Mínimo"><NumberInput value={f.participantes_minimo} min="2" onChange={v=>set("participantes_minimo",v)}/></Field><Field label="Máximo"><NumberInput value={f.participantes_maximo} min="2" max="128" onChange={v=>set("participantes_maximo",v)}/></Field><Field label="Entrada em Farejadores"><NumberInput value={f.entrada_valor} min="0" onChange={v=>set("entrada_valor",v)} disabled={f.modalidade!=="pago"}/></Field><Field label="Prêmio fixo"><NumberInput value={f.premiacao_valor} min="0" onChange={v=>set("premiacao_valor",v)} disabled={f.modalidade==="pago"}/></Field></div><div className="hint">{f.modalidade==="pago"?"Cada participante paga a entrada. O pool da edição é calculado pelas entradas efetivamente pagas.":"Não há cobrança para entrar. O prêmio fixo pode ser definido para a edição."}</div></div>
  <div className="form-section"><h3>3. Ciclo da arena</h3><div className="grid3"><Field label="Inscrições (min)"><NumberInput value={f.inscricao_minutos} min="1" onChange={v=>set("inscricao_minutos",v)}/></Field><Field label="Após lotar (min)"><NumberInput value={f.inicio_apos_lotacao_minutos} min="0" onChange={v=>set("inicio_apos_lotacao_minutos",v)}/></Field><Field label="Cada duelo (min)"><NumberInput value={f.duelo_minutos} min="1" onChange={v=>set("duelo_minutos",v)}/></Field></div><div className="flow"><span>Inscrição</span><i>→</i><span>Lotação</span><i>→</i><span>Espera</span><i>→</i><span>Batalha</span></div></div>
  <div className="form-section"><h3>4. Card e duelo</h3><div className="grid2"><Field label="Opções escolhidas no card" hint={theme?`${theme.opcoes.length} opções disponíveis no tema`:""}><NumberInput value={f.quantidade_opcoes} min="1" max={theme?.opcoes?.length||50} onChange={v=>set("quantidade_opcoes",v)}/></Field><Field label="Respostas permitidas por jogador"><NumberInput value={f.quantidade_respostas} min="1" max="50" onChange={v=>set("quantidade_respostas",v)}/></Field></div><div className="chips">{(theme?.opcoes||[]).map(x=><span key={x}>{x}</span>)}</div></div>
  <div className="form-section"><div className="section-row"><div><h3>5. Distribuição do pool</h3><p>Defina quanto vai para jogadores, organizador e sistema.</p></div><strong className={total===100?"ok":"bad"}>{total}%</strong></div><div className="grid4"><Field label="1º lugar"><NumberInput value={f.primeiro} min="0" max="100" onChange={v=>set("primeiro",v)}/></Field><Field label="2º lugar"><NumberInput value={f.segundo} min="0" max="100" onChange={v=>set("segundo",v)}/></Field><Field label="Organizador"><NumberInput value={f.organizador} min="0" max="100" onChange={v=>set("organizador",v)}/></Field><Field label="Sistema"><NumberInput value={f.sistema} min="0" max="100" onChange={v=>set("sistema",v)}/></Field></div></div>
  {err&&<div className="error">{err}</div>}<div className="modal-actions"><button className="btn ghost" type="button" onClick={onDone}>Cancelar</button><button className="btn primary" disabled={saving||total!==100} onClick={save}>{saving?"Salvando…":initial?.id_config?"Salvar alterações":"Criar configuração"}</button></div>
 </div>
}

function TournamentCreateForm({data,onDone}){
 const cats=(data?.categorias||[]).filter(x=>x.ativa!==false);
 const firstCat=cats[0]?.id||"";
 const initialTheme=(data?.temas?.[firstCat]||[])[0];
 const pad=n=>String(n).padStart(2,"0");
 const localPlus=min=>{const d=new Date(Date.now()+min*60000);return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`};
 const activeConfigs=(data?.configs||[]).filter(x=>x.ativo!==false); const [baseConfig,setBaseConfig]=useState(""); const[f,setF]=useState({title:"",category:firstCat,theme_id:initialTheme?.id||"",mode:"free",card_quantity:"2",answer_limit:"2",entry_fee:"0",prize_pool:"100",max_players:"8",registration_deadline:localPlus(15),starts_at:localPlus(20),duel_minutes:"6",prize_first:"50",prize_second:"35",organizer_percent:"10",system_percent:"5"}),[saving,setSaving]=useState(false),[err,setErr]=useState("");
 const themes=data?.temas?.[f.category]||[]; const theme=themes.find(x=>x.id===f.theme_id)||themes[0];
 useEffect(()=>{if(theme&&theme.id!==f.theme_id)setF(x=>({...x,theme_id:theme.id,card_quantity:String(Math.min(Number(x.card_quantity)||2,theme.opcoes.length)),answer_limit:String(Math.min(Number(x.answer_limit)||2,theme.opcoes.length))}))},[f.category,themes.length]);
 function applyConfig(id){setBaseConfig(id);const c=activeConfigs.find(x=>x.id_config===id);if(!c)return;const themeId=c.tema_id||c.card?.tema_id||"";const mode=c.modalidade==="pago"?"paid":"free";const now=new Date();const end=new Date(now.getTime()+Number(c.tempo?.inscricao_minutos||15)*60000);const start=new Date(end.getTime()+Math.max(1,Number(c.tempo?.inicio_apos_lotacao_minutos||5))*60000);setF(x=>({...x,title:c.nome||x.title,category:c.categoria||x.category,theme_id:themeId,mode,card_quantity:String(c.card?.quantidade_opcoes||2),answer_limit:String(c.duelo?.quantidade_respostas||2),entry_fee:String(c.entrada?.valor||0),prize_pool:String(c.premiacao?.valor||100),max_players:String(c.participantes?.maximo||8),registration_deadline:toLocalInput(end),starts_at:toLocalInput(start),duel_minutes:String(c.tempo?.duelo_minutos||6),prize_first:String(c.premiacao?.primeiro??50),prize_second:String(c.premiacao?.segundo??35),organizer_percent:String(c.premiacao?.organizador??10),system_percent:String(c.premiacao?.sistema??5)}))} const set=(k,v)=>setF(x=>({...x,[k]:v})); const total=[f.prize_first,f.prize_second,f.organizer_percent,f.system_percent].reduce((a,v)=>a+Number(v||0),0);
 async function save(){
  setErr(""); const qty=Number(f.card_quantity), answers=Number(f.answer_limit), max=Number(f.max_players), min=2, fee=Number(f.entry_fee);
  if(!f.title.trim())return setErr("Informe o nome do torneio."); if(!theme)return setErr("Selecione um tema válido."); if(max<min||max>128)return setErr("Máximo de participantes inválido.");
  if(qty<1||qty>theme.opcoes.length)return setErr(`O tema possui ${theme.opcoes.length} opções; ajuste a quantidade do card.`); if(answers<1||answers>qty)return setErr("Respostas não podem superar as opções do card.");
  if(f.mode==="paid"&&fee<=0)return setErr("Torneio pago precisa de uma entrada maior que zero."); if(f.mode==="free"&&fee!==0)return setErr("Torneio gratuito deve ter entrada 0."); if(total!==100)return setErr("A distribuição deve somar 100%.");
  if(new Date(f.registration_deadline)<=new Date()||new Date(f.starts_at)<new Date(f.registration_deadline))return setErr("As datas precisam estar no futuro e o início deve ocorrer após o fim das inscrições.");
  setSaving(true);try{await api("/tournaments",{method:"POST",body:JSON.stringify({title:f.title.trim(),category:f.category,mode:f.mode,theme_id:theme.id,theme_name:theme.nome,card_options:theme.opcoes,card_quantity:qty,answer_limit:answers,entry_fee:fee,prize_pool:Number(f.prize_pool),max_players:max,registration_deadline:new Date(f.registration_deadline).toISOString(),starts_at:new Date(f.starts_at).toISOString(),duel_minutes:Number(f.duel_minutes),prize_first:Number(f.prize_first),prize_second:Number(f.prize_second),organizer_percent:Number(f.organizer_percent),system_percent:Number(f.system_percent)})});window.dispatchEvent(new Event("torneios:changed"));onDone("Torneio criado com sucesso. O novo registro já está disponível em Edições em operação.")}catch(e){setErr(e.message)}finally{setSaving(false)}}
 return <div className="form-body">
  <div className="form-section"><h3>1. Nova edição</h3><p>Você pode iniciar a edição a partir de uma configuração ativa ou montar os dados manualmente.</p><div className="grid2"><Field label="Configuração base"><select value={baseConfig} onChange={e=>applyConfig(e.target.value)}><option value="">Sem configuração — definir manualmente</option>{activeConfigs.map(c=><option key={c.id_config} value={c.id_config}>{c.nome} · {c.modalidade==="pago"?"Pago":"Grátis"}</option>)}</select></Field></div></div><div className="form-section"><h3>2. Identidade e conteúdo</h3><div className="grid2"><Field label="Nome do torneio" wide><input autoFocus value={f.title} onChange={e=>set("title",e.target.value)} placeholder="Ex.: Arena Cinema · Filmes"/></Field><Field label="Categoria"><select value={f.category} onChange={e=>{const c=e.target.value;const t=(data?.temas?.[c]||[])[0];setF(x=>({...x,category:c,theme_id:t?.id||""}))}}>{cats.map(x=><option key={x.id} value={x.id}>{x.nome}</option>)}</select></Field><Field label="Tema"><select value={theme?.id||""} onChange={e=>set("theme_id",e.target.value)}>{themes.map(x=><option key={x.id} value={x.id}>{x.nome}</option>)}</select></Field></div><div className="chips">{(theme?.opcoes||[]).map(x=><span key={x}>{x}</span>)}</div></div>
  <div className="form-section"><h3>3. Modalidade e participantes</h3><div className="segmented"><button type="button" className={f.mode==="free"?"selected":""} onClick={()=>setF(x=>({...x,mode:"free",entry_fee:"0"}))}>🎟️ Gratuito</button><button type="button" className={f.mode==="paid"?"selected":""} onClick={()=>set("mode","paid")}>💰 Com entrada</button></div><div className="grid4"><Field label="Máximo"><NumberInput value={f.max_players} min="2" max="128" onChange={v=>set("max_players",v)}/></Field><Field label="Entrada"><NumberInput value={f.entry_fee} min="0" onChange={v=>set("entry_fee",v)} disabled={f.mode!=="paid"}/></Field><Field label="Prêmio fixo"><NumberInput value={f.prize_pool} min="0" onChange={v=>set("prize_pool",v)} disabled={f.mode==="paid"}/></Field><Field label="Minutos por duelo"><NumberInput value={f.duel_minutes} min="1" onChange={v=>set("duel_minutes",v)}/></Field></div></div>
  <div className="form-section"><h3>4. Agenda</h3><div className="grid2"><Field label="Inscrições até"><input type="datetime-local" value={f.registration_deadline} onChange={e=>set("registration_deadline",e.target.value)}/></Field><Field label="Início da batalha"><input type="datetime-local" value={f.starts_at} onChange={e=>set("starts_at",e.target.value)}/></Field></div></div>
  <div className="form-section"><h3>5. Card e premiação</h3><div className="grid2"><Field label="Opções no card" hint={theme?`${theme.opcoes.length} disponíveis`:""}><NumberInput value={f.card_quantity} min="1" max={theme?.opcoes?.length||50} onChange={v=>set("card_quantity",v)}/></Field><Field label="Respostas permitidas"><NumberInput value={f.answer_limit} min="1" max={theme?.opcoes?.length||50} onChange={v=>set("answer_limit",v)}/></Field></div><div className="grid4"><Field label="1º %"><NumberInput value={f.prize_first} min="0" max="100" onChange={v=>set("prize_first",v)}/></Field><Field label="2º %"><NumberInput value={f.prize_second} min="0" max="100" onChange={v=>set("prize_second",v)}/></Field><Field label="Organizador %"><NumberInput value={f.organizer_percent} min="0" max="100" onChange={v=>set("organizer_percent",v)}/></Field><Field label="Sistema %"><NumberInput value={f.system_percent} min="0" max="100" onChange={v=>set("system_percent",v)}/></Field></div><div className={total===100?"hint":"error"}>Distribuição: <b>{total}%</b></div></div>
  {err&&<div className="error">{err}</div>}<div className="modal-actions"><button className="btn ghost" type="button" onClick={()=>onDone("")}>Cancelar</button><button type="button" className="btn primary" disabled={saving||total!==100} onClick={save}>{saving?"Criando…":"Criar torneio"}</button></div>
 </div>
}

function Tournaments({onToast,onOpenConfig,onNewTournament}){
 const[data,setData]=useState(null),[search,setSearch]=useState(""),[status,setStatus]=useState("all"),[mode,setMode]=useState("all"),[detail,setDetail]=useState(null),[editing,setEditing]=useState(null),[loadingId,setLoadingId]=useState("");
 async function load(){try{setData(await api("/tournaments/admin/overview"))}catch(e){onToast(e.message)}}
 useEffect(()=>{load();const refresh=()=>load();window.addEventListener("torneios:changed",refresh);return()=>window.removeEventListener("torneios:changed",refresh)},[]);
 useEffect(()=>{const id=setInterval(()=>{if(!detail&&!editing)load()},15000);return()=>clearInterval(id)},[detail,editing]);
 const list=useMemo(()=>{const q=search.trim().toLowerCase();return(data?.edicoes||[]).filter(x=>(status==="all"||x.status===status)&&(mode==="all"||x.mode===mode)&&(!q||`${x.title} ${x.category} ${x.config_id||""} ${x.status}`.toLowerCase().includes(q)))},[data,search,status,mode]);
 const m=data?.metrics||{};
 async function cancel(x){if(!confirm(`Cancelar a edição "${x.title}"? Entradas pagas serão devolvidas quando aplicável.`))return;setLoadingId(x.public_id);try{await api(`/tournaments/admin/editions/${encodeURIComponent(x.public_id)}/cancel`,{method:"POST"});onToast("Edição cancelada e caixa processado.");await load()}catch(e){onToast(e.message)}finally{setLoadingId("")}}
 async function archive(x){if(!confirm(`Excluir/arquivar somente a edição "${x.title}"? O histórico financeiro e a auditoria serão preservados.`))return;setLoadingId(x.public_id);try{try{await api(`/tournaments/admin/editions/${encodeURIComponent(x.public_id)}`,{method:"DELETE"})}catch(e){if(e.status!==405)throw e;await api(`/tournaments/admin/editions/${encodeURIComponent(x.public_id)}/delete`,{method:"POST"})}onToast("Edição arquivada e removida da lista operacional.");await load()}catch(e){onToast(e.message)}finally{setLoadingId("")}}
 return <>
  <Header title="Torneios" subtitle="Centro operacional das edições: criar, acompanhar, editar, cancelar e arquivar." action={<button className="btn primary" type="button" onClick={onNewTournament}>＋ Novo torneio</button>}/>
  <div className="stats"><Stat icon="⚙" title="Configurações" value={m.configuracoes??"—"} sub={`${m.configuracoes_ativas||0} ativas`}/><Stat icon="🟡" title="Inscrições abertas" value={m.abertos??"—"}/><Stat icon="⚔️" title="Ao vivo" value={m.ao_vivo??"—"} tone="purple"/><Stat icon="🏁" title="Encerrados" value={m.encerrados??"—"}/><Stat icon="↩" title="Cancelados" value={m.cancelados??"—"}/></div>
  <div className="toolbar"><div className="search"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar torneio, categoria, configuração ou status"/></div><div className="toolbar-actions"><select value={status} onChange={e=>setStatus(e.target.value)} aria-label="Filtrar por status"><option value="all">Todos os status</option><option value="open">Inscrições abertas</option><option value="live">Ao vivo</option><option value="finished">Encerrados</option><option value="cancelled">Cancelados</option></select><select value={mode} onChange={e=>setMode(e.target.value)} aria-label="Filtrar por modalidade"><option value="all">Todas as modalidades</option><option value="free">Gratuitos</option><option value="paid">Com entrada</option></select><button className="btn ghost" type="button" onClick={load}>↻ Atualizar</button></div></div>
  <section className="card"><div className="card-head"><div><span className="eyebrow">OPERAÇÃO DAS ARENAS</span><h2>Edições de torneios</h2><p>Cada linha é uma edição concreta. Configurações e catálogo ficam nas páginas próprias.</p></div><strong>{list.length} edição(ões)</strong></div>
   <div className="table-scroll"><table><thead><tr><th>Torneio</th><th>Status</th><th>Participantes</th><th>Entrada</th><th>Prêmio</th><th>Agenda</th><th>Ações</th></tr></thead><tbody>
    {list.map(x=><tr key={x.public_id}><td><b>{x.title}</b><small>{x.config_id||"edição manual"} · {x.category}</small></td><td><span className={`badge ${x.status}`}>{labels[x.status]||x.status}</span></td><td><b>{x.participant_count}</b> / {x.max_players}</td><td>{x.mode==="paid"?`F ${money(x.entry_fee)}`:"Grátis"}</td><td>F {money(x.prize_pool)}</td><td>{dt(x.registration_deadline)}<small>Início: {dt(x.starts_at)}</small></td><td><div className="row-actions"><button className="btn ghost" type="button" onClick={async()=>{try{setDetail(await api(`/tournaments/admin/editions/${encodeURIComponent(x.public_id)}`))}catch(e){onToast(e.message)}}}>Ver</button>{x.status==="open"&&<button className="btn ghost" type="button" disabled={!!loadingId} onClick={async()=>{try{const d=await api(`/tournaments/admin/editions/${encodeURIComponent(x.public_id)}`);setEditing(d.tournament)}catch(e){onToast(e.message)}}}>Editar</button>}{(x.status==="open"||x.status==="live")&&<button className="btn danger-lite" type="button" disabled={!!loadingId} onClick={()=>cancel(x)}>{loadingId===x.public_id?"Cancelando…":"Cancelar"}</button>}{(x.status==="cancelled"||x.status==="finished")&&<button className="btn danger-lite" type="button" disabled={!!loadingId} onClick={()=>archive(x)}>{loadingId===x.public_id?"Excluindo…":"Excluir"}</button>}</div></td></tr>)}
    {!list.length&&<tr><td colSpan="7" className="empty">Nenhuma edição corresponde aos filtros atuais.</td></tr>}
   </tbody></table></div></section>
  {detail&&<Modal title={detail.tournament.title} wide onClose={()=>setDetail(null)}><EditionDetail data={detail}/></Modal>}{editing&&<Modal title={`Editar edição · ${editing.title}`} wide onClose={()=>setEditing(null)}><EditionForm initial={editing} onDone={async msg=>{setEditing(null);onToast(msg);await load()}}/></Modal>}
 </>
}
function EditionDetail({data}){const t=data.tournament,f=data.financial||{};return <div className="detail-body"><div className="detail-grid"><Stat icon="👥" title="Participantes" value={`${data.participants.length}/${t.max_players}`}/><Stat icon="🪙" title="Entradas" value={`F ${money(f.entry_volume)}`}/><Stat icon="🏆" title="Prêmios" value={`F ${money(f.winner_payout)}`}/><Stat icon="🏦" title="Organizador" value={`F ${money(f.organizer_payout)}`}/><Stat icon="💻" title="Sistema" value={`F ${money(f.system_revenue)}`}/></div><div className="detail-columns"><section className="card"><div className="card-head"><div><h2>Participantes</h2><p>Estado de cada inscrição e valor pago.</p></div></div><div className="mini-list">{data.participants.map(p=><div key={p.entry_id}><span><b>{p.username||`Usuário #${p.user_id}`}</b><small>{p.status} · {dt(p.joined_at)}</small></span><strong>F {money(p.fee_paid)}</strong></div>)}{!data.participants.length&&<div className="empty-box">Ainda sem participantes.</div>}</div></section><section className="card"><div className="card-head"><div><h2>Duels / partidas</h2><p>Chave e estado operacional.</p></div></div><div className="mini-list">{data.matches.map(m=><div key={`${m.match_id}-${m.replay}`}><span><b>Rodada {m.round} · #{m.match_number}</b><small>{m.player1||"—"} × {m.player2||"—"} · {m.status}</small></span><strong>{m.winner||"—"}</strong></div>)}{!data.matches.length&&<div className="empty-box">A chave ainda não foi criada.</div>}</div></section></div><section className="card"><div className="card-head"><div><h2>Eventos registrados</h2><p>Auditoria operacional da edição.</p></div></div><div className="event-list">{data.events.map(e=><div key={e.event_id}><b>{e.type}</b><small>{dt(e.created_at)} · ator #{e.actor_user_id||"sistema"}</small></div>)}</div></section></div>}

function EditionForm({initial,onDone}){const[f,setF]=useState({title:initial.title,max_players:String(initial.max_players),entry_fee:String(initial.entry_fee),prize_pool:String(initial.rules?.prize_pool??initial.prize_pool),duel_minutes:String(initial.rules?.duel_minutes??10),prize_first:String(initial.rules?.prize_first??50),prize_second:String(initial.rules?.prize_second??35),organizer_percent:String(initial.rules?.organizer_percent??10),system_percent:String(initial.rules?.system_percent??5),quantidade_opcoes:String(initial.rules?.card?.quantidade_opcoes??2),quantidade_respostas:String(initial.rules?.duel?.quantidade_respostas??2),registration_deadline:toLocalInput(initial.registration_deadline),starts_at:toLocalInput(initial.starts_at),mode:initial.mode}),[saving,setSaving]=useState(false),[err,setErr]=useState("");const total=[f.prize_first,f.prize_second,f.organizer_percent,f.system_percent].reduce((a,v)=>a+Number(v||0),0);const set=(k,v)=>setF(x=>({...x,[k]:v}));async function save(){setErr("");if(total!==100)return setErr("A distribuição deve somar 100%.");setSaving(true);try{await api(`/tournaments/admin/editions/${encodeURIComponent(initial.public_id)}`,{method:"POST",body:JSON.stringify({...f,max_players:Number(f.max_players),entry_fee:Number(f.entry_fee),prize_pool:Number(f.prize_pool),duel_minutes:Number(f.duel_minutes),prize_first:Number(f.prize_first),prize_second:Number(f.prize_second),organizer_percent:Number(f.organizer_percent),system_percent:Number(f.system_percent),quantidade_opcoes:Number(f.quantidade_opcoes),quantidade_respostas:Number(f.quantidade_respostas)})});onDone("Edição atualizada.")}catch(e){setErr(e.message)}finally{setSaving(false)}}return <div className="form-body"><div className="form-section"><h3>Dados da edição</h3><div className="grid2"><Field label="Nome" wide><input value={f.title} onChange={e=>set("title",e.target.value)}/></Field><Field label="Modalidade"><select value={f.mode} onChange={e=>set("mode",e.target.value)}><option value="free">Gratuito</option><option value="paid">Pago</option></select></Field><Field label="Máximo de participantes"><NumberInput value={f.max_players} min="2" max="128" onChange={v=>set("max_players",v)}/></Field><Field label="Entrada"><NumberInput value={f.entry_fee} min="0" onChange={v=>set("entry_fee",v)}/></Field><Field label="Prêmio fixo"><NumberInput value={f.prize_pool} min="0" onChange={v=>set("prize_pool",v)}/></Field><Field label="Inscrições até"><input type="datetime-local" value={f.registration_deadline} onChange={e=>set("registration_deadline",e.target.value)}/></Field><Field label="Início"><input type="datetime-local" value={f.starts_at} onChange={e=>set("starts_at",e.target.value)}/></Field><Field label="Minutos por duelo"><NumberInput value={f.duel_minutes} min="1" onChange={v=>set("duel_minutes",v)}/></Field><Field label="Opções do card"><NumberInput value={f.quantidade_opcoes} min="1" onChange={v=>set("quantidade_opcoes",v)}/></Field><Field label="Respostas"><NumberInput value={f.quantidade_respostas} min="1" onChange={v=>set("quantidade_respostas",v)}/></Field></div></div><div className="form-section"><div className="section-row"><div><h3>Distribuição financeira</h3><p>Somente edições abertas podem ser ajustadas.</p></div><strong className={total===100?"ok":"bad"}>{total}%</strong></div><div className="grid4"><Field label="1º %"><NumberInput value={f.prize_first} min="0" max="100" onChange={v=>set("prize_first",v)}/></Field><Field label="2º %"><NumberInput value={f.prize_second} min="0" max="100" onChange={v=>set("prize_second",v)}/></Field><Field label="Organizador %"><NumberInput value={f.organizer_percent} min="0" max="100" onChange={v=>set("organizer_percent",v)}/></Field><Field label="Sistema %"><NumberInput value={f.system_percent} min="0" max="100" onChange={v=>set("system_percent",v)}/></Field></div></div>{err&&<div className="error">{err}</div>}<div className="modal-actions"><button className="btn ghost" onClick={()=>onDone("Edição não alterada.")}>Cancelar</button><button className="btn primary" disabled={saving||total!==100} onClick={save}>{saving?"Salvando…":"Salvar edição"}</button></div></div>}
function toLocalInput(v){if(!v)return"";const d=new Date(v);const pad=n=>String(n).padStart(2,"0");return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}

function Configurations({onToast,onOpen}){const[rows,setRows]=useState([]),[data,setData]=useState(null),[search,setSearch]=useState("");async function load(){try{const[a,b]=await Promise.all([api("/tournaments/admin/configs"),api("/tournaments/admin/config-data")]);setRows(a.configs||[]);setData(b)}catch(e){onToast(e.message)}}useEffect(()=>{load();const refresh=()=>load();window.addEventListener("torneios:changed",refresh);return()=>window.removeEventListener("torneios:changed",refresh)},[]);const list=rows.filter(x=>`${x.nome} ${x.id_config} ${x.categoria} ${x.modalidade}`.toLowerCase().includes(search.toLowerCase()));async function toggle(c){try{await api(`/tournaments/admin/configs/${encodeURIComponent(c.id_config)}/toggle`,{method:"POST"});onToast(c.ativo?"Configuração desativada. A edição atual não é alterada.":"Configuração ativada e sincronizada.");load()}catch(e){onToast(e.message)}}async function del(c){if(!confirm(`Excluir a configuração "${c.nome}"? As edições já criadas preservam seus snapshots.`))return;try{await api(`/tournaments/admin/configs/${encodeURIComponent(c.id_config)}`,{method:"DELETE"});onToast("Configuração excluída.");load()}catch(e){onToast(e.message)}}return <><Header title="Configurações" subtitle="Modelos que controlam as próximas edições e usam o catálogo de categorias, temas e opções." action={<button className="btn primary" onClick={()=>onOpen(null)}>＋ Nova configuração</button>}/><div className="toolbar"><div className="search"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar configuração"/></div></div><div className="info-banner"><b>Regra importante:</b> alterações de categoria, tema, opções, preço e percentuais valem para as próximas edições. Uma edição aberta/ao vivo mantém o snapshot que foi criado com ela.</div><div className="config-grid">{list.map(c=><article className={`config-card ${c.ativo?"":"inactive"}`} key={c.id_config}><div className="config-top"><span className={`toggle-dot ${c.ativo?"on":""}`}/><span>{c.ativo?"ATIVA":"DESATIVADA"}</span><em>{c.edicao_ativa?"EDIÇÃO ATIVA":""}</em></div><h3>{c.nome}</h3><p>{c.id_config}</p><div className="config-meta"><span>{c.categoria}</span><span>{c.modalidade==="pago"?"💰 Pago":"🎟️ Grátis"}</span><span>Card configurável</span></div><div className="config-actions"><button className="btn ghost" onClick={async()=>{try{const d=await api(`/tournaments/admin/configs/detail?config_id=${encodeURIComponent(c.id_config)}`);onOpen(d.config)}catch(e){onToast(e.message)}}}>Editar</button><button className={`btn ${c.ativo?"danger-lite":"success-lite"}`} onClick={()=>toggle(c)}>{c.ativo?"Desativar":"Ativar"}</button><button className="btn danger-lite" onClick={()=>del(c)}>Excluir</button></div></article>)}{!list.length&&<div className="empty-box">Nenhuma configuração.</div>}</div></>}

function Catalog({onToast}){const[data,setData]=useState(null),[modal,setModal]=useState(null);async function load(){try{setData(await api("/tournaments/admin/catalog"))}catch(e){onToast(e.message)}}useEffect(()=>{load()},[]);if(!data)return <><Header title="Catálogo" subtitle="Categorias, temas e opções disponíveis para criação de torneios."/><div className="loading">Carregando catálogo…</div></>;const themes=data.temas||{};return <><Header title="Catálogo de conteúdo" subtitle="Aqui você controla as categorias, os temas e cada opção que pode aparecer nos cards." action={<button className="btn primary" onClick={()=>setModal({type:"category",item:null})}>＋ Nova categoria</button>}/><div className="info-banner"><b>Controle total do conteúdo:</b> você pode criar categorias novas (ex.: Cinema), criar temas (ex.: Filmes) e adicionar, remover ou editar opções (ex.: Terror, Comédia, Ação). Alterações não modificam cards/tournaments que já receberam snapshot.</div><div className="catalog-grid">{(data.categorias||[]).map(cat=><section className={`catalog-card ${cat.ativa?"":"disabled"}`} key={cat.id}><div className="catalog-head"><div><span className="eyebrow">CATEGORIA</span><h2>{cat.nome}</h2><small>{cat.id}</small></div><span className={`state-pill ${cat.ativa?"on":"off"}`}>{cat.ativa?"ATIVA":"DESATIVADA"}</span></div><div className="catalog-actions"><button className="btn ghost" onClick={()=>setModal({type:"category",item:cat})}>Editar categoria</button><button className="btn danger-lite" onClick={async()=>{if(!confirm(`Excluir a categoria ${cat.nome}?`))return;try{await api(`/tournaments/admin/catalog/categories/${encodeURIComponent(cat.id)}`,{method:"DELETE"});onToast("Categoria excluída.");load()}catch(e){onToast(e.message)}}}>Excluir</button></div><div className="theme-list">{(themes[cat.id]||[]).map(theme=><article className="theme-card" key={theme.id}><div><h3>{theme.nome}</h3><small>{theme.id} · {theme.opcoes.length} opções</small></div><div className="chips">{theme.opcoes.map(o=><span key={o}>{o}</span>)}</div><div className="theme-actions"><button className="btn ghost" onClick={()=>setModal({type:"theme",category:cat, item:theme})}>Editar tema/opções</button><button className="btn danger-lite" onClick={async()=>{if(!confirm(`Excluir o tema ${theme.nome}?`))return;try{await api(`/tournaments/admin/catalog/categories/${encodeURIComponent(cat.id)}/themes/${encodeURIComponent(theme.id)}`,{method:"DELETE"});onToast("Tema excluído.");load()}catch(e){onToast(e.message)}}}>Excluir</button></div></article>)}<button className="add-theme" onClick={()=>setModal({type:"theme",category:cat,item:null})}>＋ Adicionar tema nesta categoria</button></div></section>)}</div>{modal?.type==="category"&&<CategoryForm item={modal.item} onClose={()=>setModal(null)} onToast={onToast} onSaved={()=>{setModal(null);load()}}/>}{modal?.type==="theme"&&<ThemeForm category={modal.category} item={modal.item} onClose={()=>setModal(null)} onToast={onToast} onSaved={()=>{setModal(null);load()}}/>}</>}

function CategoryForm({item,onClose,onSaved,onToast}){const[f,setF]=useState({id:item?.id||"",nome:item?.nome||"",ativa:item?.ativa!==false});const[err,setErr]=useState("");async function save(){try{await api(item?`/tournaments/admin/catalog/categories/${encodeURIComponent(item.id)}`:"/tournaments/admin/catalog/categories",{method:"POST",body:JSON.stringify(f)});onToast(item?"Categoria atualizada.":"Categoria criada.");onSaved()}catch(e){setErr(e.message)}}return <Modal title={item?"Editar categoria":"Nova categoria"} onClose={onClose}><div className="form-body"><div className="form-section"><h3>Categoria</h3><Field label="ID interno" hint={item?"O ID existente não é alterado para não quebrar configurações.":"Pode ser gerado a partir do nome."}><input value={f.id} disabled={!!item} onChange={e=>setF(x=>({...x,id:e.target.value}))} placeholder={slug(f.nome)||"cinema"}/></Field><Field label="Nome"><input value={f.nome} onChange={e=>setF(x=>({...x,nome:e.target.value}))} placeholder="Cinema"/></Field><label className="check"><input type="checkbox" checked={f.ativa} onChange={e=>setF(x=>({...x,ativa:e.target.checked}))}/> Categoria disponível para novos torneios</label></div>{err&&<div className="error">{err}</div>}<div className="modal-actions"><button className="btn ghost" onClick={onClose}>Cancelar</button><button className="btn primary" onClick={save}>Salvar categoria</button></div></div></Modal>}

function ThemeForm({category,item,onClose,onSaved,onToast}){const[f,setF]=useState({id:item?.id||"",nome:item?.nome||"",opcoes:[...(item?.opcoes||[])]}),[newOpt,setNewOpt]=useState(""),[err,setErr]=useState("");function add(){const v=newOpt.trim();if(!v)return;if(f.opcoes.some(x=>x.toLowerCase()===v.toLowerCase()))return setErr("Essa opção já existe.");setF(x=>({...x,opcoes:[...x.opcoes,v]}));setNewOpt("");setErr("")}function remove(i){setF(x=>({...x,opcoes:x.opcoes.filter((_,n)=>n!==i)}))}function edit(i,v){setF(x=>({...x,opcoes:x.opcoes.map((o,n)=>n===i?v:o)}))}async function save(){try{if(!f.nome.trim())throw Error("Informe o nome do tema.");if(!f.opcoes.length)throw Error("Adicione pelo menos uma opção.");await api(item?`/tournaments/admin/catalog/categories/${encodeURIComponent(category.id)}/themes/${encodeURIComponent(item.id)}`:`/tournaments/admin/catalog/categories/${encodeURIComponent(category.id)}/themes`,{method:"POST",body:JSON.stringify(f)});onToast(item?"Tema e opções atualizados.":"Tema criado.");onSaved()}catch(e){setErr(e.message)}}return <Modal title={item?`Editar tema · ${item.nome}`:`Novo tema · ${category.nome}`} onClose={onClose} wide><div className="form-body"><div className="form-section"><h3>Identidade</h3><Field label="ID interno" hint={item?"ID preservado para manter as configurações existentes.":"Será usado para identificar o tema."}><input value={f.id} disabled={!!item} onChange={e=>setF(x=>({...x,id:e.target.value}))} placeholder={slug(f.nome)||"filmes"}/></Field><Field label="Nome do tema"><input value={f.nome} onChange={e=>setF(x=>({...x,nome:e.target.value}))} placeholder="Filmes"/></Field></div><div className="form-section"><div className="section-row"><div><h3>Opções do tema</h3><p>Adicione, remova e edite livremente. A ordem será preservada.</p></div><strong className="ok">{f.opcoes.length} opções</strong></div><div className="option-editor">{f.opcoes.map((o,i)=><div className="option-row" key={`option-${i}`}><span>{i+1}</span><input value={o} onChange={e=>edit(i,e.target.value)}/><button type="button" className="btn danger-lite" onClick={()=>remove(i)}>Remover</button></div>)}</div><div className="add-option"><input value={newOpt} onChange={e=>setNewOpt(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();add()}}} placeholder="Nova opção…"/><button className="btn primary" type="button" onClick={add}>＋ Adicionar</button></div></div>{err&&<div className="error">{err}</div>}<div className="modal-actions"><button className="btn ghost" onClick={onClose}>Cancelar</button><button className="btn primary" onClick={save}>Salvar tema e opções</button></div></div></Modal>}

function Economy({onToast}){const[cfg,setCfg]=useState(null),[form,setForm]=useState(null),[saving,setSaving]=useState(false);async function load(){try{const d=await api("/economy/admin");setCfg(d);setForm(JSON.parse(JSON.stringify(d.config)))}catch(e){onToast(e.message)}}useEffect(()=>{load()},[]);if(!form)return <><Header title="Economia" subtitle="Moeda, supply, conversão e caixa das arenas."/><div className="loading">Carregando economia…</div></>;const set=(path,v)=>setForm(x=>{const n=JSON.parse(JSON.stringify(x));let o=n;const a=path.split(".");a.slice(0,-1).forEach(k=>o=o[k]);o[a.at(-1)]=v;return n});const s=cfg?.state||{},m=cfg?.metrics||{},cash=cfg?.cash||{};async function save(){setSaving(true);try{if(Number(form.supply.autorizado)<Number(s.minted_supply||0))throw Error(`Supply autorizado não pode ficar abaixo do que já foi emitido (${money(s.minted_supply)}).`);await api("/economy/admin/config",{method:"POST",body:JSON.stringify({config:form})});onToast("Economia atualizada.");await load()}catch(e){onToast(e.message)}finally{setSaving(false)}}return <><Header title="Economia e Caixa" subtitle="Controle financeiro e monetário completo do ecossistema."/><div className="stats"><Stat icon="🪙" title={form.moeda.plural} value={money(m.total_balance)} sub="saldo distribuído"/><Stat icon="🏦" title="Supply autorizado" value={money(s.authorized_supply)}/><Stat icon="✨" title="Supply emitido" value={money(s.minted_supply)} tone="purple"/><Stat icon="📦" title="Disponível para emissão" value={money(s.remaining_supply)} tone="green"/></div><div className="cash-grid"><Stat icon="🎟️" title="Entradas recebidas" value={`F ${money(cash.entries)}`} sub={`${m.paid_tournaments||0} torneios pagos`}/><Stat icon="🏆" title="Pago aos jogadores" value={`F ${money(cash.prizes)}`}/><Stat icon="👑" title="Organizador faturou" value={`F ${money(cash.organizer)}`} sub="soma das participações de organizador"/><Stat icon="🏛️" title="Sistema faturou" value={`F ${money(cash.system)}`} sub="soma das taxas do sistema" /></div><div className="economy-grid"><section className="card"><div className="card-head"><div><h2>Moeda</h2><p>Identidade da moeda do jogo.</p></div></div><div className="grid2 pad"><FieldX label="Nome singular" value={form.moeda.nome} onChange={v=>set("moeda.nome",v)}/><FieldX label="Nome plural" value={form.moeda.plural} onChange={v=>set("moeda.plural",v)}/><FieldX label="Símbolo" value={form.moeda.simbolo} onChange={v=>set("moeda.simbolo",v)}/><FieldX label="Casas decimais" type="number" value={form.moeda.casas_decimais} onChange={v=>set("moeda.casas_decimais",v)}/></div></section><section className="card"><div className="card-head"><div><h2>Cotação / conversão XP</h2><p>Regra de conversão controlada pelo painel.</p></div></div><div className="grid2 pad"><FieldX label="XP por Farejador" type="number" value={form.conversao.xp_por_farejador} onChange={v=>set("conversao.xp_por_farejador",v)}/><FieldX label="Farejadores por conversão" type="number" value={form.conversao.farejadores_por_conversao} onChange={v=>set("conversao.farejadores_por_conversao",v)}/><FieldX label="XP mínimo" type="number" value={form.conversao.xp_minimo} onChange={v=>set("conversao.xp_minimo",v)}/><label className="check"><input type="checkbox" checked={!!form.conversao.habilitada} onChange={e=>set("conversao.habilitada",e.target.checked)}/> Conversão habilitada</label></div><div className="quote-box">Cotação atual: <b>{money(form.conversao.xp_por_farejador)} XP = {money(form.conversao.farejadores_por_conversao)} {form.moeda.plural}</b></div></section><section className="card"><div className="card-head"><div><h2>Supply</h2><p>Aumente o limite quando quiser expandir a emissão. Nunca reduz abaixo do já emitido.</p></div></div><div className="grid2 pad"><FieldX label="Supply autorizado" type="number" value={form.supply.autorizado} onChange={v=>set("supply.autorizado",v)}/><FieldX label="XP por nível" type="number" value={form.progresso.xp_por_nivel} onChange={v=>set("progresso.xp_por_nivel",v)}/></div></section><section className="card"><div className="card-head"><div><h2>Recompensas</h2><p>Pontos e XP aplicados ao resultado dos torneios.</p></div></div><div className="reward-grid"><div><h4>Pontos</h4><FieldX label="1º lugar" type="number" value={form.torneios.pontuacao.primeiro} onChange={v=>set("torneios.pontuacao.primeiro",v)}/><FieldX label="2º lugar" type="number" value={form.torneios.pontuacao.segundo} onChange={v=>set("torneios.pontuacao.segundo",v)}/><FieldX label="Demais" type="number" value={form.torneios.pontuacao.demais} onChange={v=>set("torneios.pontuacao.demais",v)}/></div><div><h4>XP</h4><FieldX label="1º lugar" type="number" value={form.torneios.xp.primeiro} onChange={v=>set("torneios.xp.primeiro",v)}/><FieldX label="2º lugar" type="number" value={form.torneios.xp.segundo} onChange={v=>set("torneios.xp.segundo",v)}/><FieldX label="Demais" type="number" value={form.torneios.xp.demais} onChange={v=>set("torneios.xp.demais",v)}/></div></div></section></div><section className="card cash-panel"><div className="card-head"><div><h2>Caixa consolidado</h2><p>O caixa registra o que entrou, saiu para jogadores, foi destinado ao organizador e ficou com o sistema.</p></div></div><div className="cash-summary"><div><span>Entradas</span><b>F {money(cash.entries)}</b></div><div><span>Prêmios</span><b>F {money(cash.prizes)}</b></div><div><span>Organizador</span><b>F {money(cash.organizer)}</b></div><div><span>Sistema</span><b>F {money(cash.system)}</b></div><div><span>Reembolsos</span><b>F {money(cash.refunds)}</b></div></div></section><section className="card users-cash"><div className="card-head"><div><h2>Quanto os usuários já faturaram</h2><p>Ranking histórico de ganhos de premiação e ganhos como organizador.</p></div></div><div className="table-scroll"><table><thead><tr><th>Usuário</th><th>Ganhos acumulados</th><th>Saldo atual</th></tr></thead><tbody>{(cfg?.user_earnings||[]).map(x=><tr key={x.user_id}><td><b>{x.username}</b><small>ID #{x.user_id}</small></td><td><b>F {money(x.earned)}</b></td><td>F {money(x.balance)}</td></tr>)}{!(cfg?.user_earnings||[]).length&&<tr><td colSpan="3" className="empty">Ainda não existem ganhos registrados.</td></tr>}</tbody></table></div></section><div className="savebar"><span>Alterações econômicas valem para as próximas operações e ficam registradas na auditoria administrativa.</span><button className="btn primary" disabled={saving} onClick={save}>{saving?"Salvando…":"Salvar economia"}</button></div></>}
function FieldX({label,value,onChange,type="text"}){return <label><span>{label}</span><input type={type} value={value??""} onChange={e=>onChange(e.target.value)}/></label>}

function App(){const[user,setUser]=useState(null),[page,setPage]=useState("tournaments"),[toast,setToast]=useState(""),[configModal,setConfigModal]=useState({type:null,item:null});useEffect(()=>{restore().then(setUser)},[]);if(!user)return <Login onAuth={setUser}/>;const nav=[["tournaments","🏆","Torneios"],["configs","⚙","Configurações"],["catalog","🧩","Catálogo"],["economy","🪙","Economia"]];const openConfig=c=>setConfigModal({type:"config",item:c||null});const openNewTournament=()=>setConfigModal({type:"tournament",item:null});return <div className="shell"><aside><div className="brand"><div>🏆</div><section><b>BATALHA</b><strong>FAREJADOR</strong><small>GESTÃO DE TORNEIOS</small></section></div><nav>{nav.map(n=><button className={page===n[0]?"active":""} onClick={()=>setPage(n[0])} key={n[0]}><i>{n[1]}</i>{n[2]}</button>)}</nav><div className="aside-note"><b>O cérebro das arenas</b><span>Criação, conteúdo, regras, economia, ativação e operação dos torneios. O monitoramento de segurança permanece no Admin.</span></div><div className="account"><span className="avatar">{user.username?.[0]?.toUpperCase()||"A"}</span><div><b>{user.username}</b><small>Administrador</small></div><button onClick={async()=>{await logout();setUser(null)}} title="Sair">↪</button></div></aside><main><div className="mobile-top"><b>🏆 Gestão de Torneios</b><button onClick={async()=>{await logout();setUser(null)}}>Sair</button></div><div className="content">{page==="tournaments"&&<Tournaments onToast={setToast} onOpenConfig={openConfig} onNewTournament={openNewTournament}/>} {page==="configs"&&<Configurations onToast={setToast} onOpen={openConfig}/>} {page==="catalog"&&<Catalog onToast={setToast}/>} {page==="economy"&&<Economy onToast={setToast}/>}</div></main><div className="mobile-nav">{nav.map(n=><button className={page===n[0]?"active":""} onClick={()=>setPage(n[0])} key={n[0]}><i>{n[1]}</i><small>{n[2]}</small></button>)}</div><Toast text={toast} onClose={()=>setToast("")}/>{configModal.type==="config"&&<Modal title={configModal.item?.id_config?"Editar configuração":"Nova configuração"} onClose={()=>setConfigModal({type:null,item:null})} wide><ConfigLoader initial={configModal.item} onDone={m=>{setConfigModal({type:null,item:null});if(m)setToast(m)}}/></Modal>}{configModal.type==="tournament"&&<Modal title="Novo torneio" onClose={()=>setConfigModal({type:null,item:null})} wide><TournamentLoader onDone={m=>{setConfigModal({type:null,item:null});if(m)setToast(m)}}/></Modal>}</div>}
function TournamentLoader({onDone}){const[d,setD]=useState(null),[err,setErr]=useState("");useEffect(()=>{Promise.all([api("/tournaments/admin/config-data"),api("/tournaments/admin/configs")]).then(([catalog,configs])=>setD({...catalog,configs:configs.configs||[]})).catch(e=>setErr(e.message))},[]);if(err)return <div className="form-body"><div className="error">{err}</div></div>;if(!d)return <div className="loading">Carregando catálogo e configurações…</div>;return <TournamentCreateForm data={d} onDone={onDone}/>}
function ConfigLoader({initial,onDone}){const[d,setD]=useState(null),[err,setErr]=useState("");useEffect(()=>{api("/tournaments/admin/config-data").then(setD).catch(e=>setErr(e.message))},[]);if(err)return <div className="form-body"><div className="error">{err}</div></div>;if(!d)return <div className="loading">Carregando modelos…</div>;return <ConfigForm initial={initial} data={d} onDone={onDone}/>}

createRoot(document.getElementById("root")).render(<App/>);
